function icons(s){return s.replace(/[🐱🐶🦊🐦🔴🔵🟡🟢⚽🚗🪆📕🧸🌼🌸🌷🎀🦋🌈⭐👑]/gu,m=>symbol(m));}
function btn(label,fn,cls=''){const b=document.createElement('button');b.innerHTML=icons(String(label)).replaceAll('◖))',speaker);b.className=cls;b.onclick=fn;return b;}
function cleanup(){voiceGeneration++;$('#voice').onended=null;drawingCleanup?.();drawingCleanup=null;clearTimeout(memoryTimer);stopRecording(true);$('#voice').pause();}
