function home(){world=null;activity=null;view(`<section class="hero">${art('studio')}<div><div class="eyebrow">מקום קטן לדמיון גדול</div><h1>הגן הקסום של רונה</h1><p>לאן נלך היום? אפשר לשחק, ליצור ולנסות שוב. בקצב שלך.</p></div></section><div class="worlds"></div><div class="home-garden" aria-label="הפרחים שלי היום">${symbol("🌼").repeat(Math.min(flowers,20))}${flowers?`<small>בגן היום: ${flowers} פרחים</small>`:""}</div><p class="guide" style="margin-top:24px">◖)) לוחצים על החברים ומקשיבים. תמיד אפשר לחזור הביתה.</p>`);Object.entries(worlds).forEach(([k,v])=>$('.worlds').append(btn(art(k)+`<strong>${v[0]}</strong><small>${v[1]}</small><small>${v[2]}</small>`,()=>openWorld(k),'world '+k)));instruction='welcome';}
const games={he:[['lotto','לוטו בגן','שומעים ומסמנים בלוח','🌼'],['find','מי מסתתרת?','מקשיבים ומוצאים אות','🔎'],['puzzle','פאזל אותיות','מחברים ארבעה חלקים','🧩'],['write','השלט שלי','כותבים ומקשטים','✍️'],['memory','זיכרון קסום','מוצאים זוגות','🌼'],['song','שיר האותיות','שומעים וזזים','♫']],math:[['lotto','לוטו מספרים','לוח מספרים מדבר','🌼'],['quantity','כמה צעצועים?','מספר וכמות עד 10','🧸'],['shop','מי בא למסיבה?','עד 5, או אתגר עד 10','🎈'],['write','כותבים מספרים','אצבע, עט או נייר','✍️'],['memory','זיכרון כמויות','מספר וכמות','🌼'],['song','שיר המספרים','סופרים עם הידיים','♫']],en:[['english','המזוודה המדברת','12 מילים חדשות','🧳'],['alphabet','חברים באנגלית','A B C D','🔤'],['memory','זיכרון תמונות','מילה בקול ותמונה','🌼'],['song','שיר הצבעים','מקשיבים ומצביעים','♫']],studio:[['draw','רק ליצור','צבעים ומדבקות','🎨'],['dress','מלבישים חברה','קישוטים של דמיון','🎀']]};
function openWorld(k){world=k;activity=null;let v=worlds[k];view(`<section class="activity-head">${art(k)}<div><div class="eyebrow">${v[1]} כאן איתך</div><h1>${v[0]}</h1><p>מה מתחשק לך לשחק?</p></div></section><div class="games"></div>`);games[k].forEach(([id,title,desc,icon])=>{let wrap=document.createElement('div');wrap.className='menu-choice';wrap.append(btn(`<b>${icon} ${title}</b><small>${desc}</small>`,()=>start(id),'game-card'));let preview=btn('◖))',()=>say(id==='lotto'?'lotto_intro':'menu_'+id));preview.className='preview';preview.setAttribute('aria-label','לשמוע '+title);wrap.append(preview);$('.games').append(wrap);});say('world_'+k);}
function start(id){activity=id;round=Math.floor(Math.random()*4);level=0;renderActivity();}
function shell(title,key,html,levels=false){taskNarration=[key];roundWon=false;view(`<div class="eyebrow">${worlds[world][0]}</div><h1>${title}</h1><div class="tools" id="topTools"></div><section class="panel">${html}<div class="session-garden" aria-label="פרחים בגן">${symbol('🌼').repeat(Math.min(flowers,10))}</div><div id="feedback" class="feedback" role="status" aria-live="polite"></div><div id="nextTools" class="tools"></div></section>`);$('#topTools').append(btn('↩ בחירת משחק',()=>openWorld(world)));if(levels)$('#topTools').append(btn(level?'🌱 בואי נתחיל':'✨ עוד אתגר',()=>parentGate(()=>{level=1-level;round=0;modal.close();renderActivity();}),'soft'));say(key);}
function feedback(ok){if(ok&&roundWon)return;if(ok){roundWon=true;flowers++;$('.choices')?.querySelectorAll('button').forEach(b=>b.disabled=true);$('.session-garden').innerHTML=symbol('🌼').repeat(Math.min(flowers,10));$('.session-garden').classList.add('celebrate');}$('#feedback').innerHTML=ok?symbol('🌼')+' יופי! פרח קטן בשבילך.':'בואי ננסה יחד. אפשר לשמוע שוב.';say(ok?'good':'try');if(ok){const preserved=[...$('#nextTools').children];$('#nextTools').replaceChildren(btn('🌸 עוד משחק',()=>{round++;renderActivity();},'primary'),btn('🎨 לסטודיו',()=>{world='studio';start('draw');},'soft'));$('#nextTools').append(...preserved);}}
function renderActivity(){({lotto,find:findLetter,puzzle,write:writing,quantity,shop,english,alphabet,memory,draw:drawing,dress,song}[activity])();}
function lotto(){let math=world==='math',count=[9,12,16][level],cells;if(math){cells=level?shuffle(Array.from({length:20},(_,i)=>i+1)).slice(0,count).sort((a,b)=>a-b):[1,2,3,4,5,6,7,8,9];}else{cells=shuffle(letters.slice(0,8));}let order=shuffle([...cells.keys()]),called=0,marked=new Set(),lotMiss=0;if(!math)cells.push('🌼');shell(math?'לוטו מספרים':'לוח האותיות','lotto_intro','<p class="instruction">שומעים, מוצאים ומסמנים</p><p class="lotto-progress" id="lottoProgress"></p><div class="lotto '+(cells.length>9?'lotto-4':'')+'"></div><div class="tools" id="callTools"></div>');function prog(){let el=$('#lottoProgress');if(el)el.textContent=marked.size+' / '+order.length+' נמצאו';}prog();function call(){if(called>=order.length){say('lotto_done');return;}let n=order[called];say(math?'number_'+cells[n]:'find_'+letters.indexOf(cells[n]));}function nextCall(){called++;prog();document.querySelectorAll('.lotto .hint-glow').forEach(x=>x.classList.remove('hint-glow'));if(called>=order.length){feedback(true);say('lotto_done');return;}call();}cells.forEach((v,i)=>{let b=btn(math?String(v):v,()=>{if(roundWon||marked.has(i))return;if(i===order[called]){$('#feedback').textContent='';marked.add(i);b.classList.add('matched');b.innerHTML=icons(String(v))+' ✓';nextCall();}else{b.classList.add('wrong-pick');b.disabled=true;lotMiss++;if(lotMiss>=2){const tb=$('.lotto').children[order[called]];if(tb)tb.classList.add('hint-glow');}$('#feedback').textContent='בואי ננסה יחד. הקשיבי שוב ומצאי בלוח.';sayQueue(['try',math?'number_'+cells[order[called]]:'find_'+letters.indexOf(cells[order[called]])]);}},'choice');b.setAttribute('aria-label',String(v));if(i===cells.length-1&&!math){b.disabled=true;b.innerHTML=symbol('🌼');}$('.lotto').append(b);});$('#callTools').append(btn('◖)) שוב',call));call();}
function findLetter(){let pool=[8,14,22][level];target=pick([...Array(8).keys()]);let ids=shuffle([target,...shuffle([...Array(pool).keys()].filter(i=>i!==target))]);shell('בלשי האותיות','find_letter','<p class="instruction">איזו אות שמענו?</p><div class="choices"></div>',true);shuffle([target,...ids.filter(i=>i!==target).slice(0,[1,2,3][level])]).forEach(i=>{let b=btn(letters[i],()=>{if(i===target){choose(true);sayQueue(['good','letter_'+i]);}else{choose(false,b);sayQueue(['find_'+target]);}taskNarration=['find_'+target];},'choice');b.setAttribute('aria-label',letters[i]);if(i===target)targetBtn=b;$('.choices').append(b);});say('find_'+target);}
