async function beginRecording(){if(permissionPending)return;permissionPending=true;$('#record').disabled=true;$('#recordStatus').textContent='מחכים להרשאת מיקרופון…';let gen=++recGeneration;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('unsupported');$('#voice').pause();let s=await navigator.mediaDevices.getUserMedia({audio:true});if(gen!==recGeneration||!$('#record')){s.getTracks().forEach(t=>t.stop());return;}stopRecording(true,false);stream=s;let chunks=[],r=new MediaRecorder(s);recorder=r;r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};r.onstop=()=>{s.getTracks().forEach(t=>t.stop());if(gen!==recGeneration)return;if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(new Blob(chunks,{type:r.mimeType||chunks[0]?.type||'audio/webm'}));if($('#playRecord')){$('#playRecord').disabled=false;$('#deleteRecord').disabled=false;$('#recordStatus').textContent='ההקלטה מוכנה. אפשר להקשיב, לנסות שוב או למחוק.';}};r.start();permissionPending=false;$('#record').disabled=false;$('#record').textContent='■ עצירה';$('#record').classList.add('recording');$('#recordStatus').textContent='מקליטים עכשיו… עד 15 שניות';recordTimer=setTimeout(()=>stopRecording(false),15000);}catch(e){if(gen!==recGeneration)return;permissionPending=false;if($('#record'))$('#record').disabled=false;stream?.getTracks().forEach(t=>t.stop());if($('#recordStatus'))$('#recordStatus').textContent='המיקרופון לא זמין או לא אושר. אפשר להמשיך לשחק ולהקשיב.';}}
function stopRecording(discard=false,invalidate=true){clearTimeout(recordTimer);if(discard&&invalidate){recGeneration++;permissionPending=false;}if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;recordPlayer?.pause();if(discard){if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=null;if($('#playRecord'))$('#playRecord').disabled=true;if($('#deleteRecord'))$('#deleteRecord').disabled=true;}if($('#record')){$('#record').disabled=false;$('#record').textContent='● תורי להקליט';$('#record').classList.remove('recording');}}
function parentGate(next=parentPanel){$('#voice').pause();$('#modalBody').innerHTML='<h2>רגע להורה</h2><p>כדי לפתוח, הקישו לפי הסדר: 7 ואז 3.</p><div class="tools" id="gate"></div><p id="gateStatus" role="status"></p>';let step=0;[3,7,5].forEach(n=>$('#gate').append(btn(n,()=>{if((step===0&&n===7)||(step===1&&n===3)){step++;if(step===2)next();}else{step=0;$('#gateStatus').textContent='ננסה שוב: 7 ואחריו 3.';}})));if(!modal.open)modal.showModal();}
function parentPanel(){$('#modalBody').innerHTML='<h2>הגן בידיים שלכם</h2><p>בלי חשבון, בלי פרסומות ובלי מעקב למידה. המשחק לא שולח קול, ציורים או תוצאות לשרת. הורדת האתר ב־GitHub Pages יוצרת תעבורת שרת רגילה.</p><p>מיקרופון: הקלטה רק בלחיצה, עד 15 שניות. נמחקת בעזיבת הפעילות, בהסתרת המסך או בסגירה. אין ציון הגייה. אפשר לשחק גם בלי הרשאה.</p><p>ללא רשת: פתחו פעם אחת עם חיבור והמתינו לאישור ההורדה. דפדפן עשוי למחוק אחסון; אין גיבוי ליצירות.</p><p>זו גרסת משחק ראשונה, לא אבחון או תוכנית קריאה מלאה. אין זיהוי כתב. בדיקת עט ודחיית כף יד תלויה במכשיר. הקריינות סינתטית ונשמרה מראש; השירים הם דקלומים.</p><div class="tools" id="parentTools"></div>';$('#parentTools').append(btn(micAllowed?'ביטול הקלטה':'אפשרות הקלטה',()=>{micAllowed=!micAllowed;if(!micAllowed)stopRecording(true);parentPanel();}),btn('מחיקת הקלטה עכשיו',()=>{stopRecording(true);$('#modalBody').append(' ההקלטה נמחקה.');}),btn('מחיקת נתוני הגן',async()=>{stopRecording(true);micAllowed=false;if('caches'in window)for(let k of await caches.keys())if(k.startsWith('rona-'))await caches.delete(k);if('serviceWorker'in navigator)for(let r of await navigator.serviceWorker.getRegistrations())if(r.scope===new URL('./',location.href).href)await r.unregister();$('#offline').textContent='החבילה הוסרה. טענו מחדש עם רשת להורדה מחדש.';$('#modalBody').innerHTML='<h2>נתוני הגן נמחקו</h2><p>לא שמרנו ציונים או קול. ציורים שכבר הורדו לקבצים נשארים בתיקיית ההורדות ויש למחוק אותם בנפרד. הרשאת המיקרופון של Chrome מנוהלת בהגדרות האתר.</p>';}));}
function printSheet(symbols){$('.print-only')?.remove();let el=document.createElement('div');el.className='print-only';el.innerHTML='<h1>מחברת התרגול · הגן הקסום של רונה</h1><p>מסתכלים על הדגם, עוברים על האות ומנסים לבד. אפשר לקשט!</p>'+symbols.slice(0,5).map(s=>`<div class="print-row"><span>${s}</span><span class="trace">${s}</span><span>____</span></div>`).join('');document.body.append(el);window.print();}
$('#repeat').innerHTML=speaker+' <span>שוב</span>';$('#home').onclick=home;$('#repeat').onclick=()=>sayQueue(taskNarration.length?taskNarration:Array.isArray(instruction)?instruction:[instruction]);$('#sound').onclick=()=>{muted=!muted;$('#sound').setAttribute('aria-pressed',muted);$('#sound').setAttribute('aria-label',muted?'הפעלת קול':'השתקת קול');$('#sound').textContent=muted?'♪ ×':'♫';if(muted){$('#voice').pause();recordPlayer?.pause();}};$('#parents').onclick=()=>parentGate();$('#closeModal').onclick=()=>modal.close();document.addEventListener('visibilitychange',()=>{if(document.hidden){stopRecording(true);$('#voice').pause();if($('#recordStatus'))$('#recordStatus').textContent='ההקלטה נמחקה כשהגן הוסתר. אפשר להקליט שוב.';}});window.addEventListener('pagehide',()=>stopRecording(true));window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();pendingInstall=e;});$('#install').onclick=async()=>{if(pendingInstall){await pendingInstall.prompt();pendingInstall=null;}else{$('#modalBody').innerHTML='<h2>הגן על מסך הבית</h2><p>ב־Chrome באנדרואיד פותחים את תפריט ⋮ ובוחרים "הוספה למסך הבית" או "התקנת אפליקציה". אם כבר הותקן, אפשר לפתוח מהסמל.</p><p>חכו לאישור "הגן מוכן ללא רשת" לפני מצב טיסה.</p>';modal.showModal();}};
let offlineTimer=setTimeout(()=>{if(!$('#offline').textContent.includes('מוכן'))$('#offline').textContent='הורדה טרם הושלמה. בדקו רשת ומקום פנוי וטענו מחדש.';},25000);if(matchMedia('(display-mode: standalone)').matches)$('#install').hidden=true;
if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='CACHE_OK'){clearTimeout(offlineTimer);$('#offline').textContent='✓ הגן מוכן ללא רשת';}if(e.data?.type==='CACHE_ERROR')$('#offline').textContent='ההורדה נכשלה. בדקו חיבור ומקום פנוי וטענו מחדש.';});navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;navigator.serviceWorker.controller?.postMessage({type:'CHECK_CACHE'});}).catch(()=>$('#offline').textContent='הורדה לא הושלמה. נסו לטעון מחדש עם רשת.');navigator.serviceWorker.addEventListener('controllerchange',()=>navigator.serviceWorker.controller?.postMessage({type:'CHECK_CACHE'}));}else $('#offline').textContent='הדפדפן לא תומך בהורדה ללא רשת';
home();
